END $$;


-- Insert Quiz Questions for Lesson: Add and Remove Tags

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 12 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 12 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'add-remove-tags' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson add-remove-tags not found in module 12';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What happens when you remove a tag from a contact?', 
    '["The contact and all their data are deleted","Only the tag is removed; the contact and their information remain","All tags are removed from the contact","The contact''s email address is deleted"]'::jsonb,
    'Only the tag is removed; the contact and their information remain',
    'Removing a tag only removes that label from the contact. The contact record, messages, notes, and all other information remain intact.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the risk of using Remove all tags in bulk?', 
    '["It only removes one selected tag","It clears every tag from selected contacts with no one-click undo","It deletes the selected contacts","It automatically adds new tags"]'::jsonb,
    'It clears every tag from selected contacts with no one-click undo',
    'Remove all tags clears every tag from the selected contacts, not just one. There is no one-click undo, so you must know which contacts should receive which tags again.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do before applying a bulk tag change?', 
    '["Apply the change immediately to all contacts","Filter carefully, review records, confirm number selected, then apply","Delete all existing tags first","Send an email to all contacts first"]'::jsonb,
    'Filter carefully, review records, confirm number selected, then apply',
    'Before bulk tagging, filter carefully, review several records from the result, confirm the number of selected contacts, apply the exact tag, check results, and open contacts to confirm the change.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
